    hero1: "Take back control", hero2: "of your identity.",
    lead: "The link that replaces your business card — privacy by default. Gather your info, a photo, your agenda, availability and network behind a simple <code>@you</code>. Messages and P2P audio/video calls are end-to-end encrypted; you edit everything via a private, key-protected link.",
    search_ph: "Search for someone…", search_btn: "Search", create: "Create my mindlog.talk", login: "Sign in", lost_key: "Lost your access key?", app_soon: "Mobile app — coming very soon",
    clients_h: "Available everywhere", cli_web: "Web", cli_android: "Android", cli_ios: "iOS", cli_desktop: "Desktop", cli_mcp: "AI · MCP", cli_live: "Live", cli_beta: "Beta", cli_soon: "Soon",
    feat_id_t: "ID card", feat_id_d: "Base attributes + custom fields, and a photo.",
    feat_agenda_t: "Agenda", feat_agenda_d: "Your events, public or kept private.",
    feat_dispo_t: "Availability", feat_dispo_d: "Calendar: free on weekdays, busy on weekends. Adjust with one click.",
    feat_rdv_t: "Meeting requests", feat_rdv_d: "Visitors book a free day and leave you a message.",
    feat_rel_t: "Connections", feat_rel_d: "Link to other profiles (friend, pro…) up to 3 degrees.",
    feat_call_t: "Encrypted chat & P2P calls", feat_call_d: "Message your contacts and start peer-to-peer (P2P) audio/video calls — end-to-end encrypted, the media goes browser-to-browser and never touches our servers. Forward secrecy (Double Ratchet), identity verification, encrypted attachments & voice notes, disappearing and view-once messages, end-to-end encrypted group chats (sender keys).",
    feat_e2e_t: "Multi-device encryption", feat_e2e_d: "Your private key lives in an encrypted vault, unlocked by your passphrase or passkey. Restore it on any device and your encrypted messages stay readable everywhere — we can never read them.",
    feat_priv_t: "Public, private & recovery", feat_priv_d: "A link to share, a secret link to edit, an email to recover access.",
    sov_h: "Sovereignty", sov_lead: "Most identity and messaging apps are US-hosted and can read your data. mindlog is built the opposite way.",
    sov_p1_t: "Hosted in France", sov_p1_d: "Your data stays in France — outside US extraterritorial law (Cloud Act, FISA).",
    sov_p2_t: "End-to-end encrypted", sov_p2_d: "Messages and calls are encrypted on your device. The server only ever sees ciphertext — we can't read them.",
    sov_p3_t: "Open source", sov_p3_d: "AGPLv3, fully auditable and self-hostable. No black box, no lock-in.",
    sov_p4_t: "Zero tracking", sov_p4_d: "No third-party cookies, no analytics, no phone number required. You are not the product.",
    sov_cmp_h: "How we compare", sov_c_fr: "Hosted in France", sov_c_e2e: "E2E encrypted", sov_c_oss: "Open source", sov_c_priv: "No tracking", sov_c_all: "All-in-one",
    sov_legend: "✓ yes · ~ partial · ✗ no", sov_cmp_note: "Compared on public information, May 2026. US providers remain subject to the US Cloud Act even when hosting in Europe.",
