    cmpf_fs: "Forward secrecy (Double Ratchet)", cmpf_verify: "Identity verification (safety number)", cmpf_attach: "Encrypted attachments & voice", cmpf_disappear: "Disappearing messages", cmpf_once: "View-once messages", cmpf_invite: "Contact by invite (no directory)", cmpf_group: "E2E group chats (sender keys)",
    mcp_h: "Drive your page from your AI",
    mcp_lead: "mindlog exposes an <strong>MCP</strong> server. Connect it to <strong>Claude</strong>, <strong>ChatGPT</strong>, Cursor or any compatible client: your assistant can read and update your card, agenda, availability and connections — in natural language.",
    mcp_tab_cloud: "☁️ Cloud hosted · free", mcp_tab_self: "⚙️ Self-hosted · open source",
    status_link: "Service status", api_docs: "API docs", privacy: "Privacy", credit: "Made by", lang_label: "Language", source: "Source code", pricing: "Pricing", store_soon: "Coming soon to",
    col_home: "Home", col_sov: "Sovereignty", col_features: "Features", col_demo: "Demo", col_mcp: "AI · MCP", col_about: "About", col_clients: "Clients",
    clients_h2: "One identity, every device", clients_lead: "<strong>mindlog.talk</strong> runs the same protocol across every surface. The web app is the reference. Android is a native Compose client with offline-first Room storage. A desktop build (Tauri) wraps the web app on Linux, macOS and Windows. An iOS build is coming via Capacitor. And the <strong>MCP</strong> connector lets any AI client (Claude, ChatGPT, Cursor…) read and write your card on your behalf.",
    clients_uni_h: "Why it's the same everywhere", clients_uni_d: "The cryptographic core (<code>src/ratchet.ts</code>) is the single reference algorithm. Web (WebCrypto) and Android (<code>javax.crypto</code>) replay the same frozen test vectors (<code>test/vectors/ratchet.json</code>) in CI — so a message sealed by the web client decrypts bit-for-bit on Android, and vice versa. Universality is a <em>checked</em> property, not a marketing claim.",
    clients_wp_h: "Cryptographic whitepaper", clients_wp_d: "A 5-page LaTeX document, in English, that specifies the protocols shipped in the current release: X3DH, Double Ratchet, sender keys for groups, PBKDF2 + AES-GCM key vault, WebAuthn-PRF unlock, safety numbers, disappearing and view-once messages, directoryless invites.",
    clients_wp_pdf: "Download PDF", clients_wp_src: "View LaTeX source",
    tour_h: "Take a tour", tour_lead: "Real screens from the native Android app. Tap a step to explore.",
    tour_home: "Home — your dashboard", tour_chat: "Chat — end-to-end encrypted", tour_reseau: "Network — your connections", tour_profil: "My card — identity & photo", tour_options: "Settings — privacy & keys",
    cl_web_d: "The reference client. Runs in any modern browser, installable as a PWA.",
    cl_android_d: "Native Kotlin + Jetpack Compose. Multi-module, offline-first (Room), Credential Manager passkeys.",
    cl_ios_d: "Capacitor build of the web client. App Store distribution planned.",
    cl_desktop_d: "Tauri 2 wrapper around the web client. Linux, macOS and Windows.",
    cl_mcp_d: "Model Context Protocol server. Plug your AI into your identity — 63 tools.",
    trust: "🇫🇷 A French solution, hosted in France — your data stays in France.",
