    adoption_trend: "+{n} this week",
    mcp_cloud_lead: "No command line, nothing to install: just add this connector to your AI. Secure sign-in via OAuth — your access key or a passkey, never shared with the assistant.",
    mcp_self_lead: "Host it yourself. Open source under <strong>AGPLv3</strong>. Run <code>npm run mcp</code> then:",
    mcp_note: "63 tools available (card, tags, agenda, availability, connections, appointments, groups, gallery, premium space & pages, billing hand-off…). Works with any MCP client: Claude, ChatGPT (connectors), Cursor…",
    price_h: "Pricing & licence",
    price_lead: "mindlog.talk is <strong>open source</strong> under the <strong>AGPLv3</strong> licence — use it and self-host it freely. A <strong>closed commercial use</strong> requires a dedicated licence (dual-licensing model).",
    pr1_tag: "Open source", pr1_t: "Self-hosted", pr1_price: "Free", pr1_cta: "View on GitHub",
    pr1_li: "<li>Free use, modification and redistribution</li><li>Unlimited self-hosting</li><li>Under <strong>AGPLv3</strong> obligations (source disclosure, including for a networked service — §13)</li><li>Community support</li>",
    pr2_tag: "Commercial use", pr2_t: "Commercial licence", pr2_price: "On request", pr2_cta: "Contact us",
    pr2_li: "<li>Integration into a <strong>proprietary / closed</strong> product</li><li><strong>SaaS</strong> offering without publishing your changes</li><li>Exemption from AGPLv3 obligations</li><li>Priority support</li>",
    pr3_tag: "Enterprise", pr3_t: "Custom", pr3_price: "On request", pr3_cta: "Contact us",
    pr3_li: "<li>Dedicated hosting (France / sovereign)</li><li>SLA, onboarding, customization</li><li>Compliance & IT integration</li><li>White-label available</li>",
    price_why_h: "Why a commercial licence?",
    price_why_d: "AGPLv3 is a strong copyleft licence: if you distribute the software <em>or offer it as a networked service</em>, you must provide the corresponding source code, including your changes, under the same licence. Ideal for the open ecosystem. If your model requires keeping your changes private or embedding mindlog into a proprietary offering, the <strong>commercial licence</strong> waives that.",
    price_contact_h: "Contact",
    price_contact_d: "For a quote or any licensing question: <a href=\"mailto:milo@mindlog.today\">milo@mindlog.today</a>.",
