    apx_pp_collect: "mindlog.talk collecte uniquement les données que vous saisissez : identifiant (handle), nom affiché, email de récupération (optionnel), événements, disponibilités et messages.",
    apx_pp_controller: "mindlog.talk est édité par <a href=\"https://le-lab.net\" target=\"_blank\" rel=\"noopener\">le-lab.net</a>.",
