    cmpf_fs: "Forward secrecy (Double Ratchet)", cmpf_verify: "Vérification d'identité (numéro de sécurité)", cmpf_attach: "Pièces jointes & voix chiffrées", cmpf_disappear: "Messages éphémères réglables", cmpf_once: "Messages à lecture unique", cmpf_invite: "Contact par invitation (sans annuaire)", cmpf_group: "Groupes chiffrés E2E (sender keys)",
    mcp_h: "Pilotez votre page depuis votre IA",
    mcp_lead: "mindlog expose un serveur <strong>MCP</strong>. Branchez-le à <strong>Claude</strong>, <strong>ChatGPT</strong>, Cursor ou tout client compatible : votre assistant lit et met à jour votre carte, agenda, disponibilités et relations — en langage naturel.",
    mcp_tab_cloud: "☁️ Cloud hébergé · gratuit", mcp_tab_self: "⚙️ Auto-hébergé · open source",
    status_link: "Statut des services", api_docs: "Doc API", privacy: "Confidentialité", credit: "Une création de", lang_label: "Langue", source: "Code source", pricing: "Tarifs", store_soon: "Bientôt sur",
    col_home: "Accueil", col_sov: "Souveraineté", col_features: "Fonctions", col_demo: "Démo", col_mcp: "IA · MCP", col_about: "À propos", col_clients: "Clients",
    clients_h2: "Une identité, tous vos appareils", clients_lead: "<strong>mindlog.talk</strong> fait tourner le même protocole sur chaque surface. L'app web est la référence. Android est un client natif en Compose, offline-first (Room). Une version bureau (Tauri) emballe l'app web pour Linux, macOS et Windows. Une version iOS arrive via Capacitor. Et le connecteur <strong>MCP</strong> permet à n'importe quel client IA (Claude, ChatGPT, Cursor…) de lire et mettre à jour votre carte à votre place.",
    clients_uni_h: "Pourquoi c'est identique partout", clients_uni_d: "Le cœur cryptographique (<code>src/ratchet.ts</code>) est l'unique algorithme de référence. Web (WebCrypto) et Android (<code>javax.crypto</code>) rejouent les mêmes vecteurs de test figés (<code>test/vectors/ratchet.json</code>) en CI — un message scellé côté web se déchiffre bit pour bit côté Android, et inversement. L'universalité est une propriété <em>vérifiée</em>, pas un argument marketing.",
    clients_wp_h: "Whitepaper cryptographique", clients_wp_d: "Document LaTeX de 5 pages, en anglais, qui spécifie les protocoles livrés dans la release courante : X3DH, Double Ratchet, sender keys pour les groupes, coffre PBKDF2 + AES-GCM, déverrouillage WebAuthn-PRF, numéros de sécurité, messages éphémères et à lecture unique, invitations sans annuaire.",
    clients_wp_pdf: "Télécharger le PDF", clients_wp_src: "Voir la source LaTeX",
    tour_h: "Visite guidée", tour_lead: "De vraies captures de l'app Android native. Touchez une étape pour explorer.",
    tour_home: "Accueil — votre tableau de bord", tour_chat: "Chat — chiffré de bout en bout", tour_reseau: "Réseau — vos connexions", tour_profil: "Ma carte — identité & photo", tour_options: "Options — confidentialité & clés",
    cl_web_d: "Le client de référence. Tourne dans tout navigateur moderne, installable en PWA.",
    cl_android_d: "Kotlin + Jetpack Compose natif. Multi-module, offline-first (Room), passkeys Credential Manager.",
    cl_ios_d: "Build Capacitor du client web. Distribution App Store prévue.",
    cl_desktop_d: "Wrapper Tauri 2 autour du client web. Linux, macOS et Windows.",
    cl_mcp_d: "Serveur Model Context Protocol. Branchez votre IA sur votre identité — 63 outils.",
    trust: "🇫🇷 Solution française, hébergée en France — vos données restent en France.",
    adoption: "{n} identités déjà créées",
    adoption_trend: "+{n} cette semaine",
    mcp_cloud_lead: "Aucune ligne de commande, rien à installer : ajoutez simplement ce connecteur dans votre IA. Connexion sécurisée par OAuth — votre clé d'accès ou une passkey, jamais transmise à l'assistant.",
    mcp_self_lead: "Hébergez-le vous-même. Open source sous licence <strong>AGPLv3</strong>. Lancez <code>npm run mcp</code> puis :",
    mcp_note: "63 outils disponibles (carte, tags, agenda, disponibilités, relations, demandes de RDV, groupes, galerie, espace & pages premium, hand-off facturation…). Compatible avec tout client MCP : Claude, ChatGPT (connecteurs), Cursor…",
    price_h: "Tarifs & licence",
    price_lead: "mindlog.talk est un logiciel <strong>open source</strong> sous licence <strong>AGPLv3</strong> — utilisez-le et hébergez-le librement. Un <strong>usage commercial fermé</strong> nécessite une licence dédiée (modèle double licence).",
    pr1_tag: "Open source", pr1_t: "Auto-hébergé", pr1_price: "Gratuit", pr1_cta: "Voir sur GitHub",
    pr1_li: "<li>Usage, modification et redistribution libres</li><li>Auto-hébergement sans limite</li><li>Sous obligations <strong>AGPLv3</strong> (publication du code, y compris pour un service en réseau — §13)</li><li>Support communautaire</li>",
    pr2_tag: "Usage commercial", pr2_t: "Licence commerciale", pr2_price: "Sur devis", pr2_cta: "Nous contacter",
    pr2_li: "<li>Intégration dans un produit <strong>propriétaire / fermé</strong></li><li>Offre <strong>SaaS</strong> sans publier vos modifications</li><li>Exemption des obligations AGPLv3</li><li>Support prioritaire</li>",
    pr3_tag: "Entreprise", pr3_t: "Sur mesure", pr3_price: "Sur devis", pr3_cta: "Nous contacter",
    pr3_li: "<li>Hébergement dédié (France / souverain)</li><li>SLA, accompagnement, personnalisation</li><li>Conformité & intégration SI</li><li>Marque blanche possible</li>",
    price_why_h: "Pourquoi une licence commerciale ?",
    price_why_d: "L'AGPLv3 est une licence « copyleft fort » : si vous distribuez le logiciel <em>ou le proposez comme service en réseau</em>, vous devez mettre à disposition le code source correspondant, y compris vos modifications, sous la même licence. Idéal pour l'écosystème libre. Si votre modèle exige de garder vos modifications privées ou d'intégrer mindlog dans une offre propriétaire, la <strong>licence commerciale</strong> vous en dispense.",
    price_contact_h: "Contact",
    price_contact_d: "Pour un devis ou toute question de licence : <a href=\"mailto:milo@mindlog.today\">milo@mindlog.today</a>.",
    // Abonnement grand public (page publique) — affiché sur l'accueil dans les deux modes.
    cpr_h: "Votre page publique",
    cpr_lead: "Votre page mindlog.talk est gratuite à vie. Passez <strong>Premium</strong> pour la rendre vraiment unique.",
    cpr_free_tag: "Gratuit", cpr_free_t: "Découverte", cpr_free_price: "Gratuit", cpr_free_cta: "Créer ma page",
    cpr_free_li: "<li>Votre @pseudo et votre page publique</li><li>Profil, agenda & prise de RDV</li><li>Messagerie & appels chiffrés de bout en bout</li><li>Image de couverture par défaut</li><li>Aucun hébergement de médias — vos contenus restent à vous</li>",
