    apx_photo_of_handle: "Foto di @{handle}",
    apx_pp_collect: "mindlog.talk raccoglie solo i dati che inserisci: identificativo (handle), nome visualizzato, email di recupero (opzionale), eventi, disponibilità e messaggi.",
    apx_pp_controller: "mindlog.talk è edito da <a href=\"https://le-lab.net\" target=\"_blank\" rel=\"noopener\">le-lab.net</a>.",
    apx_pp_cookies: "Questo sito non usa <strong>alcun cookie</strong>, nessun tracker, nessun circuito pubblicitario.",
    apx_pp_e2e_1: "I messaggi vengono cifrati end-to-end nel tuo browser prima dell'invio. Il server non può leggerli.",
